import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../presentation/providers/providers.dart';import '../../presentation/screens/app_shell.dart';import '../../presentation/screens/auth_screen.dart';import '../../presentation/screens/channel_detail_screen.dart';import '../../presentation/screens/favorites_screen.dart';import '../../presentation/screens/history_screen.dart';import '../../presentation/screens/home_screen.dart';import '../../presentation/screens/movie_detail_screen.dart';import '../../presentation/screens/movies_screen.dart';import '../../presentation/screens/player_screens.dart';import '../../presentation/screens/profile_screen.dart';import '../../presentation/screens/search_screen.dart';import '../../presentation/screens/settings_screen.dart';import '../../presentation/screens/tv_screen.dart';
final routerProvider=Provider<GoRouter>((ref){final auth=ref.watch(authProvider);return GoRouter(initialLocation:'/',redirect:(_,state){if(auth.loading)return null;final authPage=state.matchedLocation=='/login'||state.matchedLocation=='/register';if(!auth.authenticated&&!authPage)return '/login';if(auth.authenticated&&authPage)return '/';return null;},routes:[GoRoute(path:'/login',builder:(_,__)=>const AuthScreen()),GoRoute(path:'/register',builder:(_,__)=>const AuthScreen(register:true)),StatefulShellRoute.indexedStack(builder:(_,__,shell)=>AppShell(shell:shell),branches:[StatefulShellBranch(routes:[GoRoute(path:'/',builder:(_,__)=>const HomeScreen())]),StatefulShellBranch(routes:[GoRoute(path:'/tv',builder:(_,s)=>TvScreen(initialCategory:s.uri.queryParameters['category']))]),StatefulShellBranch(routes:[GoRoute(path:'/movies',builder:(_,s)=>MoviesScreen(initialCategory:s.uri.queryParameters['category']))]),StatefulShellBranch(routes:[GoRoute(path:'/search',builder:(_,__)=>const SearchScreen())]),StatefulShellBranch(routes:[GoRoute(path:'/profile',builder:(_,__)=>const ProfileScreen())])]),GoRoute(path:'/movie/:id',builder:(_,s)=>MovieDetailScreen(id:s.pathParameters['id']!)),GoRoute(path:'/channel/:id',builder:(_,s)=>ChannelDetailScreen(id:s.pathParameters['id']!)),GoRoute(path:'/player/:id',builder:(_,s)=>MoviePlayerScreen(id:s.pathParameters['id']!)),GoRoute(path:'/live/:id',builder:(_,s)=>LivePlayerScreen(id:s.pathParameters['id']!)),GoRoute(path:'/trailer',builder:(_,s){final d=s.extra!as Map<String,String>;return TrailerPlayerScreen(url:d['url']!,title:d['title']!);}),GoRoute(path:'/favorites',builder:(_,__)=>const FavoritesScreen()),GoRoute(path:'/history',builder:(_,__)=>const HistoryScreen()),GoRoute(path:'/settings',builder:(_,__)=>const SettingsScreen())]);});
